// 路径进 prompt 前做粗校验，防遍历
// 像检查门牌号：不许写「..」偷偷跑到隔壁房间，也不许以「-」开头装成选项。
for (const p of [PI_ROOT, HARNESS_ROOT]) {
  if (typeof p !== 'string' || /(^|\/)\.\.(\/|$)/.test(p) || p.startsWith('-')) {
    throw new Error(`Unsafe path ${JSON.stringify(p)}`)
  }
}
